PRAGMA foreign_keys = ON;

CREATE TABLE companies (id TEXT PRIMARY KEY, name TEXT UNIQUE NOT NULL COLLATE NOCASE, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users (id TEXT PRIMARY KEY, company_id TEXT UNIQUE NOT NULL REFERENCES companies(id) ON DELETE CASCADE, email TEXT UNIQUE NOT NULL COLLATE NOCASE, password_hash TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_systems (id TEXT PRIMARY KEY, company_id TEXT NOT NULL REFERENCES companies(id) ON DELETE CASCADE, name TEXT NOT NULL COLLATE NOCASE, description TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, UNIQUE(company_id,name));

CREATE TABLE certificate_levels (id TEXT PRIMARY KEY CHECK(id IN ('aware','aligned','assured','advanced')), code TEXT UNIQUE NOT NULL, name TEXT UNIQUE NOT NULL, description TEXT NOT NULL, score_min INTEGER NOT NULL, score_max INTEGER NOT NULL, rank INTEGER UNIQUE NOT NULL, badge_eligible INTEGER NOT NULL CHECK(badge_eligible IN (0,1)));
CREATE TABLE certificate_products (id TEXT PRIMARY KEY, level_id TEXT REFERENCES certificate_levels(id), code TEXT UNIQUE NOT NULL, product_type TEXT NOT NULL CHECK(product_type IN ('assessment','certificate')), name TEXT UNIQUE NOT NULL, description TEXT NOT NULL, cta_label TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, display_order INTEGER UNIQUE NOT NULL);
CREATE TABLE product_prices (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES certificate_products(id) ON DELETE CASCADE, amount_minor INTEGER NOT NULL, currency TEXT NOT NULL, billing_period TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, valid_from DATETIME DEFAULT CURRENT_TIMESTAMP, valid_until DATETIME);
CREATE TABLE certificate_product_features (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES certificate_products(id) ON DELETE CASCADE, label TEXT NOT NULL, display_order INTEGER NOT NULL, UNIQUE(product_id,display_order));

